#!/usr/bin/env python3
"""Generate AUDIT-RESULTS.md from the JSON result files (so documented statuses equal executed results)."""
import json, os
H = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.dirname(H)
def load(n):
    p = os.path.join(H, 'results', n)
    return {r['id']: r for r in json.load(open(p))} if os.path.exists(p) else {}
sb, sa, bb, ba = load('static_before.json'), load('static_after.json'), load('browser_before.json'), load('browser_after.json')
out = ['# Audit results – Tasbih Digital Counter', '',
       'Generated by `audit/make_report.py` from `audit/results/*.json`. Statuses: PASS / FAIL / BLOCKED / NOT TESTED / NOT APPLICABLE.',
       '"Before" = original upload; "After" = this package for static checks. Browser results combine current v2.7 HTTP route checks with the documented v2.6 headless-browser baseline; see the provenance note below. Source = static inspection; HTTP/browser checks use the local Netlify-emulating server (`audit/serve.py`).', '']
def table(title, before, after, kind):
    out.extend([f'## {title}', '', '| ID | Check | Kind | Before | After | Notes (after) |', '|---|---|---|---|---|---|'])
    for k, r in after.items():
        b = before.get(k, {}).get('status', '–'); note = (r['detail'] or '').replace('|', '/').replace('\n', ' ')[:230]
        if r['evidence'] and r['status'] != 'PASS': note += ' — ' + '; '.join(e.replace('|', '/').replace('\n', ' ')[:110] for e in r['evidence'][:3]) + (f' (+{len(r["evidence"])-3} more)' if len(r['evidence']) > 3 else '')
        out.append(f"| {k} | {r['title']} | {kind} | {b} | {r['status']} | {note} |")
    out.append('')
table('Source checks (static)', sb, sa, 'Static')
table('Browser / route checks (v2.6 Chromium baseline + v2.7 HTTP route checks)', bb, ba, 'Browser / HTTP')
n = lambda d, s: sum(1 for r in d.values() if r['status'] == s)
out += ['## Totals', '', f"- Before: static {n(sb,'PASS')} PASS / {n(sb,'FAIL')} FAIL / {n(sb,'BLOCKED')} BLOCKED; browser {n(bb,'PASS')} PASS / {n(bb,'FAIL')} FAIL",
        f"- After: static {n(sa,'PASS')} PASS / {n(sa,'FAIL')} FAIL / {n(sa,'BLOCKED')} BLOCKED; browser {n(ba,'PASS')} PASS / {n(ba,'FAIL')} FAIL", '']
extra = os.path.join(H, 'results', 'MANUAL-SECTIONS.md')
if os.path.exists(extra): out.append(open(extra, encoding='utf8').read())
open(os.path.join(ROOT, 'AUDIT-RESULTS.md'), 'w', encoding='utf8').write('\n'.join(out) + '\n')
